// MARK: - Offer (offers)

/// An offer between a brand and a creator: an invite to an open bounty, a direct offer bought from a rate card, or a re-buy of a winner. Carries the negotiation thread (max 3 counter rounds, 7-day expiry). Accepting a direct offer funds a private direct bounty from the brand wallet.
struct Offer: Codable, Hashable, Identifiable, Sendable {
    var id: String
    var kind: OfferKind
    /// Says who has the ball: awaiting_creator or awaiting_brand.
    var status: OfferStatus
    var brandId: String
    var appId: String
    var creatorId: String
    var createdByMemberId: String
    /// e.g. "Two new hooks on Glow-up reveal".
    var title: String
    /// Invite: the open bounty. Direct / re-buy: the private direct bounty, set when the offer is accepted.
    var bountyId: String?
    /// The rate card the offer was bought from.
    var rateCardId: String?
    /// Re-buy: the winning post the new hooks are based on.
    var rebuyOfPostId: String?
    /// Current total price for the deliverables (the latest counter). 0 for invites, which pay the bounty's rates.
    var amountCents: Int
    /// The opening amount.
    var originalAmountCents: Int
    /// The creator's rate-card ask at the time, for comparison.
    var askCents: Int?
    /// The market-suggested band shown inside the offer.
    var suggested: RateSuggestion?
    /// Brand plan take rate applied on top of the amount.
    var takeRate: Double
    /// amount_cents + round(amount_cents x take_rate): what the brand pays in total.
    var allInCents: Int
    var deliverables: Deliverables
    var rightsCard: RightsCard
    var turnaroundDays: Int
    /// The brand's opening note.
    var message: String
    /// Counter rounds used (0 to 3).
    var rounds: Int
    /// True once the brand wallet funded the direct bounty (on accept).
    var escrowFunded: Bool
    /// Oldest first. The first message is the opening offer.
    var thread: [OfferMessage]
    /// created_at + 7 days (reset on each counter).
    var expiresAt: Date
    var createdAt: Date
    var updatedAt: Date
    var acceptedAt: Date?
    /// Declined, expired, withdrawn or completed.
    var closedAt: Date?
}

// MARK: - Auction (auctions)

/// A creator's sealed-bid auction for a few weekly slots (Platinum and Elite). Second price: the k highest bids win and all pay the highest losing bid, or the reserve if no losing bid exists.
struct Auction: Codable, Hashable, Identifiable, Sendable {
    var id: String
    var creatorId: String
    var title: String
    var description: String
    var status: AuctionStatus
    /// 1 to 5.
    var slots: Int
    /// Minimum bid and the clearing price floor.
    var reserveCents: Int
    var deliverables: Deliverables
    var rightsCard: RightsCard
    var opensAt: Date
    /// At least 72 hours after opens_at, at most 7 days.
    var closesAt: Date
    var art: ArtSeed
    /// All bids. Sealed: the API only shows a brand its own bid until the auction closes.
    var bids: [Bid]
    var bidsCount: Int
    /// The uniform price winners pay. Set when awarded.
    var clearingPriceCents: Int?
    var winningBidIds: [String]?
    /// The private direct bounties created for the winners.
    var resultingBountyIds: [String]?
    var awardedAt: Date?
    var createdAt: Date
    var updatedAt: Date
}

// MARK: - Spec (specs)

/// A pre-made, pre-scored video that brands can license off the shelf (Spec Market). Either made speculatively by a creator or released from a bounty after 30 unused days (the original brand keeps first refusal for 7 days).
