    var video: VideoMeta
    var formatId: FormatId?
    var hookText: String
    var hookType: HookType
    /// Best-fit app category.
    var category: AppCategory
    var flowBand: ScoreBand
    /// Must be 55 or more to list.
    var flowPoints: Int
    var hookBand: ScoreBand
    var hookPoints: Int
    var qaPass: Int
    var qaWarn: Int
    var qaFail: Int
    var tags: VideoTags
    /// Licence price to the creator (the brand pays the take rate on top).
    var priceCents: Int
    /// Paid-ad usage included. Default 90.
    var paidAdsDays: Int
    var exclusive: Bool
    var rightsCard: RightsCard
    var stats: SpecStats
    /// stats.licenses equals licenses.length.
    var licenses: [SpecLicense]
    /// Released-from-bounty specs only.
    var sourceSubmissionId: String?
    var sourceBountyId: String?
    /// The brand holding first refusal.
    var sourceBrandId: String?
    /// released_at + 7 days.
    var firstRefusalEndsAt: Date?
    var listedAt: Date?
    var createdAt: Date
    var updatedAt: Date
}

